def dump(name, rows):
    p = HERE / name
    body = "\n".join(json.dumps(r, ensure_ascii=False) for r in rows) + "\n"
    p.write_bytes(body.encode("utf-8"))
    print(f"{name}: {len(rows)} rows, {p.stat().st_size} bytes")


